
.home {
  width: 100%;
  min-height: 100%;
  padding: 22px 18px 30px;
  background:
    linear-gradient(rgba(200, 155, 74, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(200, 155, 74, 0.05) 1px, transparent 1px),
    var(--night);
  background-size: 26px 26px;
}

.masthead {
  max-width: 980px;
  margin: 0 auto 20px;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 18px;
  background: var(--night-soft);
  border: 1px solid var(--gold);
  box-shadow: 4px 4px 0 rgba(200, 155, 74, 0.14);
}

.lantern-mark {
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  display: grid;
  place-items: center;
  background: var(--crimson);
  border: 1px solid var(--gold-soft);
  color: #fff2d9;
  font-size: 24px;
  font-weight: 700;
  border-radius: 8px;
  box-shadow: inset 0 0 0 3px rgba(255, 242, 217, 0.18);
}

.masthead-copy {
  min-width: 0;
}

.eyebrow {
  font-size: 11px;
  letter-spacing: 0.22em;
  color: var(--gold-soft);
  text-transform: uppercase;
}

h1 {
  font-size: 30px;
  line-height: 1.15;
  color: #fff4df;
  letter-spacing: 0.08em;
}

.subtitle {
  margin-top: 3px;
  color: var(--muted);
  font-size: 13px;
}

.intro-layout {
  max-width: 980px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(300px, 0.8fr);
  gap: 18px;
  align-items: start;
}

.story-column {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.story-block {
  padding: 18px;
  background: rgba(246, 236, 219, 0.96);
  color: var(--ink);
  border: 1px solid var(--gold);
  box-shadow: 4px 4px 0 rgba(200, 155, 74, 0.14);
}

.section-kicker {
  display: inline-block;
  margin-bottom: 8px;
  padding: 2px 8px;
  background: var(--crimson-deep);
  color: #ffe9bf;
  font-size: 11px;
  font-weight: 700;
}

.story-block h2 {
  font-size: 22px;
  color: var(--crimson-deep);
  margin-bottom: 8px;
}

.story-block p {
  font-size: 14px;
}

.story-block .preview-note {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px dashed rgba(126, 30, 37, 0.35);
  color: #6d5745;
  font-size: 12px;
}

.cast-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.cast-cell {
  min-width: 0;
  background: var(--night-soft);
  border: 1px solid var(--line);
  overflow: hidden;
}

.cast-art {
  height: 150px;
  display: grid;
  place-items: center;
  position: relative;
  background:
    repeating-linear-gradient(135deg, rgba(246, 236, 219, 0.06) 0 1px, transparent 1px 9px),
    rgba(246, 236, 219, 0.06);
  color: var(--accent);
}

.cast-art::before {
  content: '';
  position: absolute;
  inset: 14px;
  border: 1px solid currentColor;
  opacity: 0.55;
  transform: rotate(2deg);
}

.cast-art span {
  position: relative;
  z-index: 1;
  font-size: 46px;
  font-weight: 700;
}

.cast-copy {
  padding: 9px 10px;
  border-top: 2px solid var(--accent);
}

.cast-copy h3 {
  color: #fff0d5;
  font-size: 16px;
}

.cast-copy p {
  color: var(--muted);
  font-size: 11px;
}

.setup-panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px;
  background: var(--paper);
  color: var(--ink);
  border: 1px solid var(--gold);
  box-shadow: 4px 4px 0 rgba(200, 155, 74, 0.14);
}

.field {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.field-label {
  font-size: 13px;
  font-weight: 700;
  color: var(--crimson-deep);
}

.segmented {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}

.segment {
  min-height: 42px;
  padding: 7px 8px;
  border: 1.5px solid rgba(36, 26, 20, 0.35);
  background: #fff8ea;
  color: var(--ink);
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.16s ease, color 0.16s ease, transform 0.16s ease;
}

.segment:hover {
  border-color: var(--crimson);
}

.segment.selected {
  background: var(--crimson);
  border-color: var(--crimson-deep);
  color: #fff4df;
}

.segment:active {
  transform: translateY(1px);
}

.opening-segments {
  grid-template-columns: 1fr;
}

.opening-segment {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  min-height: 56px;
}

.opening-segment small {
  font-size: 11px;
  font-weight: 400;
  opacity: 0.85;
}

.field-hint {
  font-size: 11px;
  color: #6d5745;
  min-height: 15px;
}

.start-button {
  width: 100%;
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 1px solid var(--gold-soft);
  background: var(--crimson-deep);
  color: #fff3d8;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 3px 3px 0 rgba(126, 30, 37, 0.35);
}

.start-button:hover:not(:disabled) {
  background: #8f222b;
}

.start-button:disabled {
  opacity: 0.6;
  cursor: wait;
}

.start-arrow {
  font-size: 19px;
}

.error-message {
  color: #a32b2b;
  font-size: 12px;
}

.game-screen {
  max-width: 860px;
  margin: 0 auto;
  padding: 16px;
  background: var(--paper);
  color: var(--ink);
  border: 1px solid var(--gold);
  box-shadow: 4px 4px 0 rgba(200, 155, 74, 0.14);
}

.game-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
  padding-bottom: 9px;
  border-bottom: 2px solid var(--crimson-deep);
  color: #6d5745;
  font-size: 12px;
}

.game-tag {
  padding: 2px 8px;
  background: var(--crimson);
  color: #fff4df;
  font-weight: 700;
}

.maintext {
  font-size: 14px;
  line-height: 1.8;
  white-space: normal;
}

.option-block {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px dashed rgba(36, 26, 20, 0.3);
}

.option-text {
  white-space: pre-wrap;
  font-size: 13px;
  color: #4d3b2d;
}

@media (max-width: 820px) {
  .intro-layout {
    grid-template-columns: 1fr;
  }

  .cast-art {
    height: 120px;
  }
}

@media (max-width: 560px) {
  .home {
    padding: 14px 10px 20px;
  }

  h1 {
    font-size: 24px;
  }

  .lantern-mark {
    width: 44px;
    height: 44px;
    flex-basis: 44px;
    font-size: 20px;
  }

  .cast-row {
    grid-template-columns: 1fr;
  }

  .cast-art {
    height: 170px;
  }
}
